/**
 * Lab films live on R2 (served by /media/labs/*). Generated by
 * `pnpm video:labs:publish` after an upload; do not edit by hand.
 */

export type PublishedLabFilm = {
  /** Seconds. */
  duration: number;
  /** ISO date of the upload. */
  uploaded: string;
  portrait: boolean;
  sha256: string;
};

export const PUBLISHED_LAB_FILMS: Record<
  string,
  Partial<Record<'en' | 'zh', PublishedLabFilm>>
> = {};
